// Pseudo‑code: simple SFU forwarder decision (Node.js-like)
// This is illustrative: accept packets, decide which outgoing streams to forward

function onIncomingPacket(streamId, packet, meetingMeta) {
  const participants = meetingMeta.activeParticipants;
  // Select who should receive this stream: only send high resolution when client supports it
  for (const participant of participants) {
    if (!participant.isConnected) continue;
    // prioritize audio always
    if (packet.isAudio) {
      forwardTo(participant, packet);
      continue;
    }
    // video: apply subscriber caps and simulcast rules
    if (participant.networkGood && participant.wantsHighRes && meetingMeta.highResAvailable) {
      forwardTo(participant, packet.highResLayer);
    } else if (participant.networkGood) {
      forwardTo(participant, packet.mediumLayer);
    } else {
      // low bandwidth, forward low layer or skip to preserve CPU/bandwidth
      forwardTo(participant, packet.lowLayer);
    }
  }
}

